import base64
import json
import zlib

_DATA = ""


def load_protocol_mass() -> dict:
    raw = zlib.decompress(base64.b64decode(_DATA.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


PROTOCOL_MASS = load_protocol_mass()
WEEKS = PROTOCOL_MASS["weeks"]
SUBSTITUTIONS = PROTOCOL_MASS["substitutions"]
